package com.signalchain.app.dsp
import kotlin.math.*
object SpectralSubtraction{fun apply(x:FloatArray,fp:FrameParams,noise:FloatArray,n:Int=x.size,alpha:Double=1.2,beta:Double=.1,smooth:Double=.7,use:Boolean=true):FloatArray{val o=DoubleArray(n+fp.fftSize);val w=DoubleArray(o.size);var prev=DoubleArray(noise.size){1.0};val wp=DoubleArray(fp.fftSize){if(it<fp.frameLen)fp.win[it]else 0.0};for(i in 0 until fp.numFrames){val idx=i*fp.hopLen;val a=DoubleArray(fp.fftSize){k->if(k<fp.frameLen)x.getOrElse(idx+k){0f}*fp.win[k]else 0.0};val s=Fft.rfft(a);val clean=Array(s.size){k->val m2=s[k].re*s[k].re+s[k].im*s[k].im;val mc=if(use)max(m2-alpha*noise[k],beta*m2)else m2;val post=max(m2/(noise[k]+1e-10)-1,0.0);var g=smooth*prev[k]+(1-smooth)*post/(post+1);g=max(g,.25);prev[k]=g;val mag=sqrt(mc)*g;val ph=atan2(s[k].im,s[k].re);Complex(mag*cos(ph),mag*sin(ph))};val z=Fft.irfft(clean,fp.fftSize);for(k in 0 until fp.fftSize){val p=idx+k;o[p]+=z[k]*wp[k];w[p]+=wp[k]*wp[k]}};return FloatArray(n){(o[it]/(w[it]+1e-10)).toFloat()}}}
